17	
18	import java.time.LocalDate;
19	
20	import org.springframework.util.StringUtils;
21	import org.springframework.validation.Errors;
22	import org.springframework.validation.Validator;
23	
24	/**
25	 * <code>Validator</code> for <code>Pet</code> forms.
26	 * <p>
27	 * We're not using Bean Validation annotations here because it is easier to define such
28	 * validation rule in Java.
29	 * </p>
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 */
34	public class PetValidator implements Validator {
35	
36		private static final String REQUIRED = "required";
37	
38		private static final int MAX_NAME_LENGTH = 30;
39	
40		@Override
41		public void validate(Object obj, Errors errors) {
42			Pet pet = (Pet) obj;
43			String name = pet.getName();
44			// name validation
45			if (!StringUtils.hasText(name)) {
46				errors.rejectValue("name", REQUIRED, REQUIRED);
47			}
48			else if (name.length() > MAX_NAME_LENGTH) {
49				errors.rejectValue("name", "size", "Name must be no more than 30 characters");
50			}
51	
52			// type validation
53			if (pet.isNew() && pet.getType() == null) {
54				errors.rejectValue("type", REQUIRED, REQUIRED);
55			}
56	
57			// birth date validation
58			if (pet.getBirthDate() == null) {
59				errors.rejectValue("birthDate", REQUIRED, REQUIRED);
60			}
61			else if (pet.getBirthDate().isAfter(LocalDate.now())) {
62				errors.rejectValue("birthDate", "typeMismatch.birthDate");
63			}
64		}
65	
66		/**
67		 * This Validator validates *just* Pet instances
68		 */
69		@Override
70		public boolean supports(Class<?> clazz) {
71			return Pet.class.isAssignableFrom(clazz);
72		}
73	
74	}
