package org.springframework.samples.petclinic.owner;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class PetTests {

	@Test
	void microchipNumberIsTrimmedAndItsSpacesRemoved() {
		Pet pet = new Pet();
		pet.setMicrochipNumber(" 985 141 000 123 456 ");
		assertThat(pet.getMicrochipNumber()).isEqualTo("985141000123456");
	}

	@Test
	void blankMicrochipNumberBecomesNone() {
		Pet pet = new Pet();
		pet.setMicrochipNumber("   ");
		assertThat(pet.getMicrochipNumber()).isNull();
	}

	@Test
	void emptyMicrochipNumberBecomesNone() {
		Pet pet = new Pet();
		pet.setMicrochipNumber("");
		assertThat(pet.getMicrochipNumber()).isNull();
	}

	@Test
	void nullMicrochipNumberStaysNone() {
		Pet pet = new Pet();
		pet.setMicrochipNumber(null);
		assertThat(pet.getMicrochipNumber()).isNull();
	}

	@Test
	void dashesInMicrochipNumberAreKept() {
		Pet pet = new Pet();
		pet.setMicrochipNumber("985-141-000-123-456");
		assertThat(pet.getMicrochipNumber()).isEqualTo("985-141-000-123-456");
	}

}

