	@Nested
	class MicrochipNumber {

		private static final String NUMBER = "985141000123456";

		/**
		 * Every load of the owner returns new instances, so the bound pet and the owner's
		 * pet differ, as they do with a real repository. A value only reaches the saved
		 * owner if {@code updatePetDetails} copies it.
		 */
		private void ownerLoadsFreshPettyWithMicrochipNumber(String microchipNumber) {
			given(owners.findById(TEST_OWNER_ID)).willAnswer(invocation -> {
				Owner fresh = new Owner();
				Pet freshPetty = new Pet();
				freshPetty.setId(TEST_PET_ID);
				freshPetty.setName("petty");
				freshPetty.setBirthDate(LocalDate.of(2010, 1, 1));
				freshPetty.setMicrochipNumber(microchipNumber);
				fresh.addPet(freshPetty);
				return Optional.of(fresh);
			});
		}

		private Owner savedOwner() {
			ArgumentCaptor<Owner> saved = ArgumentCaptor.forClass(Owner.class);
			verify(owners).saveAndFlush(saved.capture());
			return saved.getValue();
		}

		// ---- add form ----

		@Test
		void addWithoutMicrochipNumberSavesNoneAndDoesNotQuery() throws Exception {
			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", ""))
				.andExpect(status().is3xxRedirection())
				.andExpect(view().name("redirect:/owners/{ownerId}"))
				.andExpect(flash().attribute("message", "New Pet has been Added"));

			assertThat(savedOwner().getPet("Betty").getMicrochipNumber()).isNull();
			verifyNoInteractions(pets);
		}

		@Test
		void addWithBlankMicrochipNumberSavesNone() throws Exception {
			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", "   "))
				.andExpect(status().is3xxRedirection());

			assertThat(savedOwner().getPet("Betty").getMicrochipNumber()).isNull();
		}

		@Test
		void addRemovesSpacesFromMicrochipNumber() throws Exception {
			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", " 985 141 000 123 456 "))
				.andExpect(status().is3xxRedirection());

			assertThat(savedOwner().getPet("Betty").getMicrochipNumber()).isEqualTo(NUMBER);
			verify(pets).existsByMicrochipNumber(NUMBER);
		}

		@Test
		void addAcceptsFifteenDigits() throws Exception {
			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", NUMBER))
				.andExpect(status().is3xxRedirection());

			assertThat(savedOwner().getPet("Betty").getMicrochipNumber()).isEqualTo(NUMBER);
		}

		@Test
		void addWithDashedNumberIsRejectedAndNotSaved() throws Exception {
			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", "985-141-000-123-456"))
				.andExpect(status().isOk())
				.andExpect(view().name("pets/createOrUpdatePetForm"))
				.andExpect(model().errorCount(1))
				.andExpect(model().attributeHasFieldErrorCode("pet", "microchipNumber", "microchipNumber.invalid"))
				.andExpect(content().string(containsString("must be 15 digits")));

			verify(owners, never()).saveAndFlush(any());
		}

		@Test
		void addWithNumberOfAnotherOwnersPetShowsOnlyIsAlreadyInUse() throws Exception {
			given(pets.existsByMicrochipNumber(NUMBER)).willReturn(true);

			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", " 985141000123456"))
				.andExpect(status().isOk())
				.andExpect(view().name("pets/createOrUpdatePetForm"))
				.andExpect(model().errorCount(1))
				.andExpect(model().attributeHasFieldErrorCode("pet", "microchipNumber", "duplicate"))
				.andExpect(content().string(containsString("is already in use")))
				// "Leo" of George Franklin holds the number in the seed-like scenario; the
				// page must not name either of them.
				.andExpect(content().string(not(containsString("Leo"))))
				.andExpect(content().string(not(containsString("Franklin"))));

			verify(owners, never()).saveAndFlush(any());
		}

		@Test
		void addReportsThreeErrorsOneOnMicrochipNumber() throws Exception {
			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "petty")
					.param("type", "hamster")
					.param("birthDate", LocalDate.now().plusDays(1).toString())
					.param("microchipNumber", "123"))
				.andExpect(status().isOk())
				.andExpect(model().errorCount(3))
				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"))
				.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch.birthDate"))
				.andExpect(model().attributeHasFieldErrorCode("pet", "microchipNumber", "microchipNumber.invalid"))
				.andExpect(content().string(containsString("is already in use")))
				.andExpect(content().string(containsString("invalid date")))
				.andExpect(content().string(containsString("must be 15 digits")));

			verify(owners, never()).saveAndFlush(any());
			verifyNoInteractions(pets);
		}

		// ---- edit form ----

		@Test
		void editFormShowsStoredMicrochipNumber() throws Exception {
			ownerLoadsFreshPettyWithMicrochipNumber(NUMBER);

			mockMvc.perform(get("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID))
				.andExpect(status().isOk())
				.andExpect(content().string(containsString("Microchip number")))
				.andExpect(content().string(
						containsString("id=\"microchipNumber\" name=\"microchipNumber\" value=\"" + NUMBER + "\"")));
		}

		@Test
		void editFormForPetWithoutNumberShowsEmptyField() throws Exception {
			ownerLoadsFreshPettyWithMicrochipNumber(null);

			mockMvc.perform(get("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID))
				.andExpect(status().isOk())
				.andExpect(content().string(containsString("Microchip number")))
				.andExpect(content().string(containsString("id=\"microchipNumber\" name=\"microchipNumber\" value=\"\"")));
		}

		@Test
		void editReplacesStoredNumberOnOwnersPet() throws Exception {
			ownerLoadsFreshPettyWithMicrochipNumber(NUMBER);

			mockMvc
				.perform(post("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID).param("name", "petty")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", "985141000654321"))
				.andExpect(status().is3xxRedirection());

			assertThat(savedOwner().getPet(TEST_PET_ID).getMicrochipNumber()).isEqualTo("985141000654321");
		}

		@Test
		void editWithEmptyFieldRemovesStoredNumberFromOwnersPet() throws Exception {
			ownerLoadsFreshPettyWithMicrochipNumber(NUMBER);

			mockMvc
				.perform(post("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID).param("name", "petty")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", ""))
				.andExpect(status().is3xxRedirection());

			assertThat(savedOwner().getPet(TEST_PET_ID).getMicrochipNumber()).isNull();
		}

		@Test
		void editSavingPetWithItsOwnNumberIsAccepted() throws Exception {
			ownerLoadsFreshPettyWithMicrochipNumber(NUMBER);
			// The number exists (on petty itself): only the query that excludes the pet
			// lets the edit through.
			given(pets.existsByMicrochipNumber(anyString())).willReturn(true);
			given(pets.existsByMicrochipNumberAndIdNot(NUMBER, TEST_PET_ID)).willReturn(false);

			mockMvc
				.perform(post("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID).param("name", "petty")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", "985 141 000 123 456"))
				.andExpect(status().is3xxRedirection());

			assertThat(savedOwner().getPet(TEST_PET_ID).getMicrochipNumber()).isEqualTo(NUMBER);
			verify(pets).existsByMicrochipNumberAndIdNot(NUMBER, TEST_PET_ID);
		}

		@Test
		void editToAnotherPetsNumberIsRejected() throws Exception {
			// petty holds the number; doggy is edited to it.
			given(pets.existsByMicrochipNumberAndIdNot(NUMBER, TEST_PET_ID + 1)).willReturn(true);

			mockMvc
				.perform(post("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID + 1)
					.param("name", "doggy")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", "985 141 000 123 456"))
				.andExpect(status().isOk())
				.andExpect(view().name("pets/createOrUpdatePetForm"))
				.andExpect(model().errorCount(1))
				.andExpect(model().attributeHasFieldErrorCode("pet", "microchipNumber", "duplicate"))
				.andExpect(content().string(containsString("is already in use")));

			verify(owners, never()).saveAndFlush(any());
		}

		@Test
		void editReportsTwoErrorsOneOnMicrochipNumber() throws Exception {
			given(pets.existsByMicrochipNumberAndIdNot(NUMBER, TEST_PET_ID)).willReturn(true);

			mockMvc
				.perform(post("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID).param("name", "petty")
					.param("birthDate", "")
					.param("microchipNumber", NUMBER))
				.andExpect(status().isOk())
				.andExpect(model().errorCount(2))
				.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "required"))
				.andExpect(model().attributeHasFieldErrorCode("pet", "microchipNumber", "duplicate"))
				.andExpect(content().string(containsString("is required")))
				.andExpect(content().string(containsString("is already in use")));

			verify(owners, never()).saveAndFlush(any());
		}

		// ---- duplicates caught by the database ----

		@Test
		void createMicrochipConstraintIsReportedOnMicrochipNumber() throws Exception {
			given(owners.saveAndFlush(any(Owner.class))).willThrow(new DataIntegrityViolationException(
					"Unique index or primary key violation: \"PUBLIC.UNIQUE_PET_MICROCHIP_NUMBER\""));

			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", NUMBER))
				.andExpect(status().isOk())
				.andExpect(view().name("pets/createOrUpdatePetForm"))
				.andExpect(model().errorCount(1))
				.andExpect(model().attributeHasFieldErrorCode("pet", "microchipNumber", "duplicate"));
		}

		@Test
		void editMicrochipConstraintIsReportedOnMicrochipNumber() throws Exception {
			given(owners.saveAndFlush(any(Owner.class)))
				.willThrow(new DataIntegrityViolationException("duplicate key: unique_pet_microchip_number"));

			mockMvc
				.perform(post("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID).param("name", "petty")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", NUMBER))
				.andExpect(status().isOk())
				.andExpect(view().name("pets/createOrUpdatePetForm"))
				.andExpect(model().errorCount(1))
				.andExpect(model().attributeHasFieldErrorCode("pet", "microchipNumber", "duplicate"));
		}

		@Test
		void createNameConstraintIsStillReportedOnNameOnly() throws Exception {
			given(owners.saveAndFlush(any(Owner.class)))
				.willThrow(new DataIntegrityViolationException("Duplicate key: unique_owner_pet_name"));

			mockMvc
				.perform(post("/owners/{ownerId}/pets/new", TEST_OWNER_ID).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", NUMBER))
				.andExpect(status().isOk())
				.andExpect(model().errorCount(1))
				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
		}

		@Test
		void editNameConstraintIsStillReportedOnNameOnly() throws Exception {
			given(owners.saveAndFlush(any(Owner.class)))
				.willThrow(new DataIntegrityViolationException("Duplicate key: unique_owner_pet_name"));

			mockMvc
				.perform(post("/owners/{ownerId}/pets/{petId}/edit", TEST_OWNER_ID, TEST_PET_ID).param("name", "petty")
					.param("birthDate", "2015-02-12")
					.param("microchipNumber", NUMBER))
				.andExpect(status().isOk())
				.andExpect(model().errorCount(1))
				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
		}

	}

}

