	@Test
	void showOwnerShowsPetsMicrochipNumber() throws Exception {
		Owner george = george();
		george.getPet("Max").setMicrochipNumber("985141000123456");
		given(this.owners.findById(TEST_OWNER_ID)).willReturn(Optional.of(george));

		String body = mockMvc.perform(get("/owners/{ownerId}", TEST_OWNER_ID))
			.andExpect(status().isOk())
			.andReturn()
			.getResponse()
			.getContentAsString();

		assertThat(body).containsPattern("<dt>Microchip number</dt>\\s*<dd>985141000123456</dd>");
	}

	@Test
	void showOwnerShowsEmptyMicrochipNumberForPetWithoutOne() throws Exception {
		String body = mockMvc.perform(get("/owners/{ownerId}", TEST_OWNER_ID))
			.andExpect(status().isOk())
			.andReturn()
			.getResponse()
			.getContentAsString();

		assertThat(body).containsPattern("<dt>Microchip number</dt>\\s*<dd></dd>");
		assertThat(body).doesNotContainPattern("<dt>Microchip number</dt>\\s*<dd>none</dd>");
	}

